function __lexicographical_compare_typescript() { return ["function lexicographical_compare<I extends Iter<unknown>, J extends Iter<ValueOf<I>>>(\n    f0: I, l0: I, f1: J, l1: J, r: Relation<ValueOf<I>>,\n): boolean {\n    while (true) {\n        if (equal(f1, l1)) return false;\n        if (equal(f0, l0)) return true;\n\n        const a = source(f0);\n        const b = source(f1);\n        if (r(a, b)) return true;\n        if (r(b, a)) return false;\n\n        f0 = successor(f0);\n        f1 = successor(f1);\n    }\n}","const left = seq([9, 7, 1]);\nconst right = seq([9, 5, 8]);\nconst before = lexicographical_compare(begin(left), end(left), begin(right), end(right), gt);\nprint(\"Left comes first in descending order: \" + before);"]; }

function __lexicographical_compare_documentation() { return ["Compara dos rangos usando la relación de orden r. Decide el primer par que difiere. Si uno es prefijo propio del otro, va primero el más corto.","Compares two ranges using the ordering relation r. The first differing pair decides. A proper prefix precedes the longer range.","function lexicographical_compare<I extends Iter<unknown>, J extends Iter<ValueOf<I>>>(\n    f0: I, l0: I, f1: J, l1: J, r: Relation<ValueOf<I>>,\n): boolean"]; }

function __lexicographical_compare_references() { return ["Elements of Programming, ch. 7, p. 127."]; }

function __lexicographical_compare_usage() {
    const left = seq([9, 7, 1]);
    const right = seq([9, 5, 8]);
    const before = lexicographical_compare(begin(left), end(left), begin(right), end(right), gt);
    print("Left comes first in descending order: " + before);
}

