function __lexicographical_equal_typescript() { return ["function lexicographical_equal<I extends Iter<unknown>, J extends Iter<ValueOf<I>>>(\n    f0: I, l0: I, f1: J, l1: J,\n): boolean {\n    return lexicographical_equivalent(f0, l0, f1, l1, eq);\n}","const left = seq([\"a\", \"b\"]);\nconst right = seq([\"a\", \"b\", \"c\"]);\nconst same = lexicographical_equal(begin(left), end(left), begin(right), end(right));\nprint(\"Equal ranges: \" + same);"]; }

function __lexicographical_equal_documentation() { return ["Comprueba que ambos rangos tengan la misma longitud y elementos iguales en cada posición correspondiente.","Checks that the ranges have the same length and equal elements at every corresponding position.","function lexicographical_equal<I extends Iter<unknown>, J extends Iter<ValueOf<I>>>(\n    f0: I, l0: I, f1: J, l1: J,\n): boolean"]; }

function __lexicographical_equal_references() { return ["Elements of Programming, ch. 7, p. 125."]; }

function __lexicographical_equal_usage() {
    const left = seq(["a", "b"]);
    const right = seq(["a", "b", "c"]);
    const same = lexicographical_equal(begin(left), end(left), begin(right), end(right));
    print("Equal ranges: " + same);
}

