function __lexicographical_equivalent_typescript() { return ["function lexicographical_equivalent<I extends Iter<unknown>, J extends Iter<ValueOf<I>>>(\n    f0: I, l0: I, f1: J, l1: J, r: Relation<ValueOf<I>>,\n): boolean {\n    const [a, b] = find_mismatch(f0, l0, f1, l1, r);\n    return equal(a, l0) && equal(b, l1);\n}","const sameDigitSum = relation<number>((a, b) => digitSum(a) === digitSum(b));\nconst left = seq([12, 23]);\nconst right = seq([21, 32], \"right\", undefined, \"stream\");\nconst equivalent = lexicographical_equivalent(\n    begin(left), end(left), begin(right), end(right), sameDigitSum,\n);\nprint(\"Equivalent by digit sum: \" + equivalent);"]; }

function __lexicographical_equivalent_documentation() { return ["Comprueba que ambos rangos tengan la misma longitud y que r considere equivalentes todos los pares correspondientes.","Checks that the ranges have the same length and r considers every corresponding pair equivalent.","function lexicographical_equivalent<I extends Iter<unknown>, J extends Iter<ValueOf<I>>>(\n    f0: I, l0: I, f1: J, l1: J, r: Relation<ValueOf<I>>,\n): boolean"]; }

function __lexicographical_equivalent_references() { return ["Elements of Programming, ch. 7, p. 124."]; }

function __lexicographical_equivalent_usage() {
    const sameDigitSum = relation((a, b) => digitSum(a) === digitSum(b));
    const left = seq([12, 23]);
    const right = seq([21, 32], "right", undefined, "stream");
    const equivalent = lexicographical_equivalent(begin(left), end(left), begin(right), end(right), sameDigitSum);
    print("Equivalent by digit sum: " + equivalent);
}

