function __insertion_sort_typescript() { return ["function insertion_sort<T>(f: Iter<T>, l: Iter<T>, r: Relation<T>) {\n    if (equal(f, l)) return;\n    const c = successor(f);\n    if (equal(c, l)) return;\n\n    // create a sentinel\n    const min = min_element_nonempty(f, l, r);\n    if (! equal(min, f)) {\n        rotate_right_by_one_nonempty(f, successor(min));\n        increment_custom_stat(\"Misplaced elements\");\n        register_move_distance(distance(f, min));\n    }\n    insertion_sort_suffix_nonempty(c, l, r);\n}","function linear_insert_unguarded<T>(c: Iter<T>, r: Relation<T>) {\n    if ( ! call(r, c, predecessor(c))) return c;\n\n    increment_custom_stat(\"Misplaced elements\");\n\n    const value = source_move(c);\n    const d = shift_right_while_unguarded(c, bind(r, value));\n    sink_move(d, value);\n    register_move_distance(distance(d, c));\n    return d;\n}\n\nfunction insertion_sort_suffix_nonempty<T>(f: Iter<T>, l: Iter<T>, r: Relation<T>) {\n    //precondition: ! equal(f, l)\n    let c = successor(f);\n    while ( ! equal(c, l)) {\n        linear_insert_unguarded(c, r);\n        c = successor(c);\n    }\n}\n\n\nregister_custom_stat(\"Misplaced elements\");\n\n// var s = seq([1, 2, 3, 4, 5], \"s\", lt);\n// var s = seq([1, 2], \"s\", lt);\n\n// const s = seq(array_random(), \"s\", lt);\n// var s = seq(array_all_equal(), \"s\", lt);\n// var s = seq(array_ascending(), \"s\", lt);\nconst s = seq(array_descending(), lt);\n\ninsertion_sort(begin(s), end(s), lt);\nprint(s);"]; }

function __insertion_sort_usage() {
    function linear_insert_unguarded(c, r) {
        if (!call(r, c, predecessor(c)))
            return c;
        increment_custom_stat("Misplaced elements");
        const value = source_move(c);
        const d = shift_right_while_unguarded(c, bind(r, value));
        sink_move(d, value);
        register_move_distance(distance(d, c));
        return d;
    }
    function insertion_sort_suffix_nonempty(f, l, r) {
        //precondition: ! equal(f, l)
        let c = successor(f);
        while (!equal(c, l)) {
            linear_insert_unguarded(c, r);
            c = successor(c);
        }
    }
    register_custom_stat("Misplaced elements");
    // var s = seq([1, 2, 3, 4, 5], "s", lt);
    // var s = seq([1, 2], "s", lt);
    // const s = seq(array_random(), "s", lt);
    // var s = seq(array_all_equal(), "s", lt);
    // var s = seq(array_ascending(), "s", lt);
    const s = seq(array_descending(), lt);
    insertion_sort(begin(s), end(s), lt);
    print(s);
}

