function __rotate_forward_typescript() { return ["function rotate_forward<T>(f: Iter<T>, m: Iter<T>, l: Iter<T>) {\n    // precondition: mutable_bounded_range(f, l) ∧ f ≺ m ≺ l\n\n    const ref = { f, m };\n    rotate_forward_step(ref, l);\n    f = ref.f;\n    m = ref.m;\n    const m_prime = f;\n    while ( ! equal(m, l)) {\n        const ref = { f, m };\n        rotate_forward_step(ref, l);\n        f = ref.f;\n        m = ref.m;\n    }\n    return m_prime;\n}","function exchange_values<T, U>(x: Iter<T>, y: Iter<U>) {\n    const t = source(x);\n    sink(x, source(y));\n    sink(y, t);\n}\n\nfunction rotate_forward_step<T>(ref: { f: Iter<T>; m: Iter<T> }, l: Iter<T>) {\n    // precondition: mutable_bounded_range(ref.f, l) ∧ ref.f ≺ ref.m ≺ l\n    let f = ref.f;\n    let m = ref.m;\n    let c = m;\n    do {\n        exchange_values(f, c);\n        f = successor(f);\n        c = successor(c);\n\n        if (equal(f, m)) {\n            m = c;\n        }\n    } while ( ! equal(c, l));\n    ref.f = f;\n    ref.m = m;\n}\n\nconst s = seq(array_random(), \"s\", undefined, \"sll\");\nrotate_forward(begin(s), successor(begin(s), 3), end(s));\nprint(s);"]; }

function __rotate_forward_references() { return ["Elements of Programming, ch. 10, pp. 181–182 (rotate_forward_nontrivial)."]; }

function __rotate_forward_usage() {
    function exchange_values(x, y) {
        const t = source(x);
        sink(x, source(y));
        sink(y, t);
    }
    function rotate_forward_step(ref, l) {
        // precondition: mutable_bounded_range(ref.f, l) ∧ ref.f ≺ ref.m ≺ l
        let f = ref.f;
        let m = ref.m;
        let c = m;
        do {
            exchange_values(f, c);
            f = successor(f);
            c = successor(c);
            if (equal(f, m)) {
                m = c;
            }
        } while (!equal(c, l));
        ref.f = f;
        ref.m = m;
    }
    const s = seq(array_random(), "s", undefined, "sll");
    rotate_forward(begin(s), successor(begin(s), 3), end(s));
    print(s);
}

