function __rotate_random_access_nontrivial_typescript() { return ["function rotate_random_access_nontrivial<T>(f: Iter<T>, m: Iter<T>, l: Iter<T>) {\n    const p = k_rotate_from_permutation_random_access(f, m, l);\n    return rotate_cycles(f, m, l, p);\n}","function cycle_from<T>(i: Iter<T>, f: IteratorPermutation<T>) {\n    const tmp = source(i);\n    let j = i;\n    let k = f(i);\n    while ( ! equal(k, i)) {\n        sink(j, source(k));\n        j = k;\n        k = f(k);\n    }\n    sink(j, tmp);\n}\n\nfunction rotate_cycles<T>(f: Iter<T>, m: Iter<T>, l: Iter<T>, from: IteratorPermutation<T>) {\n    let d = gcd(distance(f, m), distance(m, l));\n\n    while (d != 0) {\n        --d;\n        cycle_from(successor(f, d), from);\n    }\n    return successor(f, distance(m, l));\n}\n\nfunction k_rotate_from_permutation_random_access<T>(f: Iter<T>, m: Iter<T>, l: Iter<T>) {\n    const k = distance(m, l);\n    const n_minus_k = distance(f, m);\n    const m_prime = successor(f, distance(m, l));\n\n    return function(x: Iter<T>) {\n        if ( distance(x, m_prime) > 0) return successor(x, n_minus_k);\n        return predecessor(x, k);\n    };\n}\n\nconst s = seq(array_random(12));\nrotate_random_access_nontrivial(begin(s), successor(begin(s), 3), end(s));\nprint(s);"]; }

function __rotate_random_access_nontrivial_references() { return ["Elements of Programming, ch. 10, p. 179."]; }

function __rotate_random_access_nontrivial_usage() {
    function cycle_from(i, f) {
        const tmp = source(i);
        let j = i;
        let k = f(i);
        while (!equal(k, i)) {
            sink(j, source(k));
            j = k;
            k = f(k);
        }
        sink(j, tmp);
    }
    function rotate_cycles(f, m, l, from) {
        let d = gcd(distance(f, m), distance(m, l));
        while (d != 0) {
            --d;
            cycle_from(successor(f, d), from);
        }
        return successor(f, distance(m, l));
    }
    function k_rotate_from_permutation_random_access(f, m, l) {
        const k = distance(m, l);
        const n_minus_k = distance(f, m);
        const m_prime = successor(f, distance(m, l));
        return function (x) {
            if (distance(x, m_prime) > 0)
                return successor(x, n_minus_k);
            return predecessor(x, k);
        };
    }
    const s = seq(array_random(12));
    rotate_random_access_nontrivial(begin(s), successor(begin(s), 3), end(s));
    print(s);
}

