function __add_to_counter_typescript() { return ["function add_to_counter<I extends ForwardIterator>(\n    f: I, l: I, op: Operation<ValueOf<I>>, x: ValueOf<I>, z: ValueOf<I>,\n): ValueOf<I> {\n    if (x === z) return z;\n\n    while (!equal(f, l)) {\n        const current = source(f);\n        if (current === z) {\n            sink(f, x);\n            return z;\n        }\n        x = op(current, x);\n        sink(f, z);\n        f = successor(f);\n    }\n    return x;\n}","const slots = seq([1, 5, 0]);\nadd_to_counter(begin(slots), end(slots), add, 4, 0);\nprint(slots);"]; }

