function __partition_point_n_typescript() { return ["function partition_point_n<I extends Iter<unknown>>(f: I, n: number, p: Predicate<ValueOf<I>>): I {\n    while (n != 0) {\n        const h = half(n);\n        const m = successor(f, h);\n\n        if (p(source(m))) {\n            n = h;\n        } else {\n            n -= h + 1;\n            f = successor(m);\n        }\n    }\n    return f;\n}","const d = seq([1, 5, 1, 1, 3, 3, 3, 7, 3, 2, 6, 4], even);\n\nconst p = partition_point_n(begin(d), size(d), even);\nconst partitionValue = source(p);\nprint('partition point: ' + partitionValue);"]; }

function __partition_point_n_references() { return ["Elements of Programming, ch. 6, p. 104.","From Mathematics to Generic Programming, ch. 10, p. 193 (ch10.h)."]; }

function __partition_point_n_usage() {
    const d = seq([1, 5, 1, 1, 3, 3, 3, 7, 3, 2, 6, 4], even);
    const p = partition_point_n(begin(d), size(d), even);
    const partitionValue = source(p);
    print('partition point: ' + partitionValue);
}

