function __partition_point_n_forward_typescript() { return ["function partition_point_n_forward<T>(f: Iter<T>, n: number, p: Predicate<T>): [Iter<T>, number] {\n    let t = n;\n    while (n != 0) {\n        const h = half(n);\n        const m = successor(f, h);\n\n        if (p(source(m))) {\n            n = h;\n        } else {\n            n -= h + 1;\n            t -= h + 1;\n            f = successor(m);\n        }\n    }\n    return [f, t];\n}","const eq3 = predicate(x => x == 3);\nconst gt3 = predicate(x => x > 3);\nconst gte3 = predicate(x => x >= 3);\n\nconst d = seq([1, 1, 1, 1, 3, 3, 3, 3, 3, 7, 8, 9], eq3);\n\nconst lb = partition_point_n_forward(begin(d), size(d), gte3);\nconst ub = partition_point_n_forward(lb[0], lb[1], gt3);\n\nlet f = lb[0];\nconst l = ub[0];\n\nwhile ( ! equal(f, l)) {\n    const partitionValue = source(f);\n    print(partitionValue + \", \");\n    f = successor(f);\n}"]; }

function __partition_point_n_forward_references() { return ["Elements of Programming, ch. 6, p. 104 (variant of partition_point_n that also returns a count)."]; }

function __partition_point_n_forward_usage() {
    const eq3 = predicate(x => x == 3);
    const gt3 = predicate(x => x > 3);
    const gte3 = predicate(x => x >= 3);
    const d = seq([1, 1, 1, 1, 3, 3, 3, 3, 3, 7, 8, 9], eq3);
    const lb = partition_point_n_forward(begin(d), size(d), gte3);
    const ub = partition_point_n_forward(lb[0], lb[1], gt3);
    let f = lb[0];
    const l = ub[0];
    while (!equal(f, l)) {
        const partitionValue = source(f);
        print(partitionValue + ", ");
        f = successor(f);
    }
}

