function __find_adjacent_mismatch_typescript() { return ["function find_adjacent_mismatch<I extends Iter<unknown>>(\n    f: I, l: I, r: Relation<ValueOf<I>>,\n): I {\n    if (equal(f, l)) return l;\n\n    let previous = source(f);\n    f = successor(f);\n    while (!equal(f, l)) {\n        const current = source(f);\n        if (!r(previous, current)) return f;\n        previous = current;\n        f = successor(f);\n    }\n    return l;\n}","const d = seq([1, 4, 3, 8], \"d\", undefined, \"stream\");\nconst result = find_adjacent_mismatch(begin(d), end(d), lt);\n\nif (equal(result, end(d))) {\n    print(\"All adjacent pairs are strictly increasing.\");\n} else {\n    const value = source(result);\n    print(\"First element that breaks the ordering: \" + value);\n}"]; }

function __find_adjacent_mismatch_documentation() { return ["Devuelve el segundo iterador del primer par adyacente que falla r. Si todos los pares cumplen r, devuelve l.","Returns the second iterator of the first adjacent pair that fails r. Returns l if every pair satisfies r.","function find_adjacent_mismatch<I extends Iter<unknown>>(\n    f: I, l: I, r: Relation<ValueOf<I>>,\n): I"]; }

function __find_adjacent_mismatch_references() { return ["Elements of Programming, ch. 6, p. 100."]; }

