function __find_subsequence_n_naive_1_typescript() { return ["function find_subsequence_n_naive_1<T>(f: Iter<T>, fn: number, s: Iter<T>, sn: number, r: Relation<T>): [Iter<T>, number] {\n    if (sn == 0) return [f, fn];\n\n    while (true) {\n        if (fn < sn) return [f, 0];\n\n        let tf = f;\n        let ts = s;\n        let n = sn;\n        while (true) {\n            if (n == 0) return [f, fn];\n            if ( ! r(source(tf), source(ts))) break;\n            --n;\n            ts = successor(ts);\n            tf = successor(tf);\n        }\n        let skip = 1;\n        if (n != sn) {\n            const eqf = predicate<T>(function eqf(x) { return r(x, source(tf)); });\n            const it = find_if(s, ts, eqf);\n\n            if (equal(it, ts)) {\n                skip = sn - n;\n            }\n        }\n        fn -= skip;\n        f = successor(f, skip);\n    }\n\n    return [f, fn];\n}","const haystack = seq(array_from(\"Until death it is all life\"));\n//var haystack = seq(array_from(\"Until dedead it is all life\"), \"seq\");\nconst sub = seq(array_from(\"dead\"));\n\nconst r = find_subsequence_n_naive_1(begin(haystack), size(haystack), begin(sub), size(sub), eq);\nconst it = r[0];\nconst n = r[1];\n\nif (n == 0) {\n    print(\"Subsequence not found\");\n} else {\n    print(\"Subsequence found at: \");\n    const offset = distance(begin(haystack), it);\n    print(offset);\n}"]; }

