function __partitioned_typescript() { return ["function partitioned<T>(f: Iter<T>, l: Iter<T>, p: Predicate<T>) {\n    const it0 = find_if(f, l, p);\n    const it1 = find_if_not(it0, l, p);\n    return equal(it1, l);\n}","const d = seq(array_random(), \"d\", even, undefined, true);\nconst [f, l] = rng(d);\n\nif (partitioned(f, l, even)) {\n    print('The sequence is already p-partitioned.');\n} else {\n    print('The sequence is not p-partitioned, partitioning...');\n\n    const p = partition_semistable(f, l, even);\n\n    if (partitioned(f, l, even)) {\n        print('Now the sequence is p-partitioned.');\n    } else {\n        print('Impossible, this line will never be executed.');\n    }\n}"]; }

function __partitioned_references() { return ["Elements of Programming, ch. 6, p. 102."]; }

function __partitioned_usage() {
    const d = seq(array_random(), "d", even, undefined, true);
    const [f, l] = rng(d);
    if (partitioned(f, l, even)) {
        print('The sequence is already p-partitioned.');
    }
    else {
        print('The sequence is not p-partitioned, partitioning...');
        const p = partition_semistable(f, l, even);
        if (partitioned(f, l, even)) {
            print('Now the sequence is p-partitioned.');
        }
        else {
            print('Impossible, this line will never be executed.');
        }
    }
}

