function __potential_partition_point_typescript() { return ["function potential_partition_point<I extends ForwardIterator>(f: I, l: I, p: Predicate<ValueOf<I>>): I {\n    return count_if_not_basis(f, l, p, f);\n}","const d = seq(array_random(), even);\nconst [f, l] = rng(d);\nconst m = potential_partition_point(f, l, even);\n\nprint(\"After p-partitioning the partition point would ocurr here:\");\nconst offset = distance(begin(d), m);\nprint(offset);\nconst partitionValue = source(m);\nprint(partitionValue);\n\nprint(\"Let's verify...\");\nconst p = partition_semistable(f, l, even);\nif (equal(m, p)) {\n    print(\"Yeah!\");\n} else {\n    print('Impossible, this line will never be executed.');\n}"]; }

function __potential_partition_point_documentation() { return ["Devuelve la posición donde terminaría el grupo que falla p si se particionara el rango. Requiere poder recorrerlo más de una vez.","Returns the position where the group failing p would end after partitioning. Requires a multipass range.","function potential_partition_point<I extends ForwardIterator>(f: I, l: I, p: Predicate<ValueOf<I>>): I"]; }

function __potential_partition_point_references() { return ["Elements of Programming, ch. 11, p. 189, exercise 11.2 (companion implementation in eop.h)."]; }

function __potential_partition_point_usage() {
    const d = seq(array_random(), even);
    const [f, l] = rng(d);
    const m = potential_partition_point(f, l, even);
    print("After p-partitioning the partition point would ocurr here:");
    const offset = distance(begin(d), m);
    print(offset);
    const partitionValue = source(m);
    print(partitionValue);
    print("Let's verify...");
    const p = partition_semistable(f, l, even);
    if (equal(m, p)) {
        print("Yeah!");
    }
    else {
        print('Impossible, this line will never be executed.');
    }
}

