function __max_element_typescript() { return ["function max_element<T>(f: Iter<T>, l: Iter<T>, r: Relation<T>) {\n    if (equal(f, l)) return l;\n\n    let m = f;\n    f = successor(f);\n\n    while ( ! equal(f, l)) {\n        if ( ! r(source(f), source(m))) {\n            m = f;\n        }\n        f = successor(f);\n    }\n    return m;\n}","const s = seq(array_random());\n\nconst l = end(s);\n\nconst m = max_element(begin(s), l, lt);\nif ( ! equal(m, l)) {\n    const maximum = source(m);\n    print(\"The max element is: \" + maximum);\n} else {\n    print(\"An empty sequence has no max element\");\n}"]; }

function __max_element_usage() {
    const s = seq(array_random());
    const l = end(s);
    const m = max_element(begin(s), l, lt);
    if (!equal(m, l)) {
        const maximum = source(m);
        print("The max element is: " + maximum);
    }
    else {
        print("An empty sequence has no max element");
    }
}

