function __swap_ranges_typescript() { return ["function swap_ranges<T, U>(f: Iter<T>, l: Iter<T>, f1: Iter<U>) {\n    while ( ! equal(f, l)) {\n        exchange_values(f, f1);\n        f = successor(f);\n        f1 = successor(f1);\n    }\n    return f1;\n}","function exchange_values<T, U>(x: Iter<T>, y: Iter<U>) {\n    const t = source(x);\n    sink(x, source(y));\n    sink(y, t);\n}\n\nconst s = seq(array_ascending());\nconst z = seq(array_all_equal(size(s), '-'));\n\nswap_ranges(successor(begin(s), 5), end(s), begin(z));\n\nprint(z);"]; }

